    "up.flap.info": "\uC774\uB959\uD560 \uB54C \uC704\uB85C \uD280\uC5B4 \uC624\uB974\uB294 \uD798\uC774 \uCEE4\uC838\uC694. \uBE60\uB974\uAC8C \uC774\uB959\uD560\uC218\uB85D \uD6A8\uACFC\uAC00 \uCEE4\uC11C, \uACE8\uC9DC\uAE30 \uBC14\uB2E5\uC5D0\uC11C \uC190\uC744 \uC798 \uB5BC\uBA74 \uD6E8\uC52C \uB192\uC774 \uB0A0\uC544\uC694.",
    "up.slide.info": "\uB0B4\uB9AC\uB9C9\uC5D0\uC11C \uB204\uB974\uACE0 \uC788\uC744 \uB54C \uB354 \uBE68\uB9AC \uAC00\uC18D\uD558\uACE0, \uBBF8\uB044\uB7EC\uC9C8 \uB54C\uC758 \uC800\uD56D\uC774 \uC904\uC5B4 \uCD5C\uACE0 \uC18D\uB3C4\uAC00 \uC62C\uB77C\uAC00\uC694.",
    "up.magnet.info": "\uD3AD\uADC4 \uC8FC\uBCC0\uC758 \uBB3C\uACE0\uAE30\uB97C \uB04C\uC5B4\uC640\uC694. \uB2E8\uACC4\uAC00 \uC624\uB97C\uC218\uB85D \uB354 \uBA3C \uBB3C\uACE0\uAE30\uAE4C\uC9C0 \uB04C\uB824\uC640\uC694.",
    "up.glide.info": "\uC190\uC744 \uB5BC\uACE0 \uB0B4\uB824\uC624\uB294 \uB3D9\uC548 \uB35C \uBB34\uAC81\uAC8C \uB5A8\uC5B4\uC9C0\uACE0 \uACF5\uAE30 \uC800\uD56D\uC774 \uC904\uC5B4\uC11C \uB354 \uBA40\uB9AC \uB0A0\uC544\uAC00\uC694.",
    "up.scarf.info": "\uB208\uBCF4\uB77C\uC5D0 \uC7A1\uD788\uB294 \uC21C\uAC04 \uD138\uBAA9\uB3C4\uB9AC\uB85C \uBC84\uD2F0\uACE0 \uC55E\uC73C\uB85C \uD280\uC5B4 \uB098\uAC00\uC694. \uD55C \uD310\uC5D0 \uBC84\uD2F0\uAE30 \uD69F\uC218\uB9CC\uD07C \uC4F8 \uC218 \uC788\uC5B4\uC694.",
