      ctx.beginPath();
      ctx.moveTo(X(-400), Y(305));
      for (let x = -400; x <= VW + 400; x += 30) ctx.lineTo(X(x), Y(300 + Math.sin(x * 0.011) * 10 + Math.sin(x * 0.031) * 4));
      ctx.lineTo(X(VW + 400), H + 10);
      ctx.lineTo(X(-400), H + 10);
